create policy org_update on public.video_renders as permissive for update to public using ((org_id IN ( SELECT auth_editor_org_ids() AS auth_editor_org_ids))) with check ((org_id IN ( SELECT auth_editor_org_ids() AS auth_editor_org_ids)));
